"""AcmeCSV invoice parser."""

import csv
import io
import re


def _amount_to_cents(raw):
    s = raw.strip()
    negative = False
    if s.startswith("(") and s.endswith(")"):
        negative = True
        s = s[1:-1].strip()
    if s.startswith("$"):
        s = s[1:]
    s = s.replace(",", "").strip()
    if not s:
        raise ValueError(f"empty amount: {raw!r}")
    if "." in s:
        whole, frac = s.split(".", 1)
        if not whole:
            whole = "0"
        if not frac.isdigit() or not whole.lstrip("-").isdigit() and not (
            whole.startswith("-") and whole[1:].isdigit()
        ):
            # allow plain digits around decimal
            if not (whole.isdigit() or (whole.startswith("-") and whole[1:].isdigit()) or whole == "-"):
                pass
        if len(frac) > 2:
            frac = frac[:2]
        elif len(frac) < 2:
            frac = frac.ljust(2, "0")
        cents = int(whole or "0") * 100 + int(frac)
    else:
        cents = int(s) * 100
    if negative:
        cents = -cents
    return cents


def parse(text):
    """Parse AcmeCSV invoice text into a list of row dicts.

    Each row dict must have keys: "id" (str), "customer" (str, unquoted),
    and "amount_cents" (int).
    """
    if not text or not text.strip():
        return []
    reader = csv.DictReader(io.StringIO(text))
    rows = []
    for record in reader:
        rows.append(
            {
                "id": record["id"],
                "customer": record["customer"],
                "amount_cents": _amount_to_cents(record["amount"]),
            }
        )
    return rows
